function validate([arr]) {
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 1000) return 'arr needs 1 to 1000 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 2 || v > 1e9)) return 'Each value is an integer from 2 to 10^9.';
  if (new Set(arr).size !== arr.length) return 'The values of arr must be distinct.';
  return null;
}

