  const MOD = 1_000_000_007n;
  arr.sort((a, b) => a - b);
  const index = new Map();
  for (let i = 0; i < arr.length; i++) {
    index.set(arr[i], i);
  }
  // dp[i]: number of trees whose root is arr[i] (BigInt keeps products exact).
  const dp = new Array(arr.length).fill(1n);
  let total = 0n;
  for (let i = 0; i < arr.length; i++) {
    for (let j = 0; j < i; j++) {
      if (arr[i] % arr[j] !== 0) {
        continue;
      }
      const k = index.get(arr[i] / arr[j]);
      if (k !== undefined) {
        dp[i] = (dp[i] + dp[j] * dp[k]) % MOD;
      }
    }
    total = (total + dp[i]) % MOD;
  }
  return Number(total);
}

