function generate(rand, size) {
  const pick = (list) => list[Math.floor(rand() * list.length)];
  if (size === 'small') {
    const pool = rand() < 0.5 ? [2, 3, 4, 5, 6, 8, 9, 10, 12, 16, 18, 20, 24, 27, 30, 36] : Array.from({ length: 40 }, (_, i) => i + 2);
    const n = 1 + Math.floor(rand() * 8);
    const chosen = new Set();
    while (chosen.size < Math.min(n, pool.length)) chosen.add(pick(pool));
    return [[...chosen]];
  }
  // Large: mostly 7-smooth numbers (many factor pairs) plus some random values.
  const smooth = [];
  for (let a = 1; a <= 1e9; a *= 2)
    for (let b = a; b <= 1e9; b *= 3)
      for (let c = b; c <= 1e9; c *= 5)
        for (let d = c; d <= 1e9; d *= 7)
          if (d >= 2) smooth.push(d);
  const n = 1000;
  const chosen = new Set();
  while (chosen.size < n) chosen.add(rand() < 0.8 ? pick(smooth) : 2 + Math.floor(rand() * (1e9 - 1)));
  return [[...chosen]];
}
